entries[249805] = { ["name"] = "Undreamt God's Oozing Vestige", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\nEquip: You have a high chance to spatter your target with volatile phlegm, dealing ( 4 * 1 ) Nature damage per sec and stacking up to 5 times.\n\nUpon 5 stacks or the enemy's demise, the phlegm violently consumes itself to deal 372 Nature damage split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%.\n\"The ooze never seems to stop.\"\nSell Price:" }
entries[249806] = { ["name"] = "Radiant Plume", ["text"] = "Binds when picked up\nUnique-Equipped: Plume of Belo'ren (1)\nTrinket\n+9 [Agility or Strength]\nEquip: The Plume's radiance grants you 21 Mastery, waning over 60 sec before reigniting to full incandescence. The Plume's power also regenerates while out of combat.\nUse: While out of combat, invoke the Plume's dual nature to transform it into an Umbral Plume. (5 Min Cooldown)\nSell Price:" }
entries[249807] = { ["name"] = "The Eternal Egg", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\nEquip: Your abilities have a chance to grant you a protective shell, absorbing up to 25% of incoming damage for 6 sec or until 1198 damage has been prevented. If the shell expires without breaking, gain 42 Haste for 12 sec.\nSell Price:" }
entries[249808] = { ["name"] = "Litany of Lightblind Wrath", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nUse: Invoke the litany to apply Beacon of Lightblind Wrath to an enemy for 30 sec. Your next 5 harmful spells call down a blast of Light to deal 290 Holy damage to the target.\n\n5 injured allies are shielded for the same amount, absorbing 50% of damage taken while the shield holds. (1 Min, 30 Sec Cooldown)\n\"Are you with the Light?\"\nSell Price:" }
entries[249809] = { ["name"] = "Locus-Walker's Ribbon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Mastery\nEquip: Casting spells has a high chance to tempt you with the power of the Void, increasing your Intellect by 20 for 10 sec.\n\nEach temptation permanently increases this effect by 5%, up to 10 times, diminishing quickly upon leaving combat.\n\"\"Do you wish to learn more of the Void? It has many lessons to teach us amongst its maddening whispers.\" - Locus-Walker\"\nSell Price:" }
entries[249810] = { ["name"] = "Shadow of the Empyrean Requiem", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nEquip: Your harmful spells have a high chance to call cosmic shards from the heavens to slice your target and one nearby enemy for ( 321 * 1 ) Cosmic damage.\n\nIf either enemy is below 35% health, gain 321 Haste for 12 sec as you speed them to their fate.\nSell Price:" }
entries[249811] = { ["name"] = "Light of the Cosmic Crescendo", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nEquip: Your healing has a high chance to inflict Cosmic Crescendo on a nearby enemy, dealing 2 Cosmic damage every 3 sec until their death, stacking up to 25 times.\n\nHum a cosmic hymn every 2 sec, consuming a Cosmic Crescendo stack if any ally is below 60% health to heal them and up to 4 injured allies for ( 256 * 1 ) split between them. Healing increased by 30% per additional ally, up to 150%.\n\"There was a time when her song filled hearts with hope.\"\nSell Price:" }
