entries[249950] = { ["name"] = "Night Ender's Pauldrons", ["text"] = "Binds when picked up\nShoulder Plate\n21 Armor\n+7 [Strength or Intellect]\n+10 Stamina\n+ 9 Haste\n+ 5 Mastery\nClasses: Warrior\nRage of the Night Ender (0/5)\nNight Ender's Breastplate\nNight Ender's Fists\nNight Ender's Tusks\nNight Ender's Chausses\nNight Ender's Pauldrons\n(2) Set Arms: Mortal Strike and Cleave damage increased by 5%. Colossus Smash increases damage taken by an additional 5%.\n(2) Set Fury: Rampage damage increased by 10% and Odyn's Fury damage increased by 10%.\n(2) Set Protection: Shield Slam damage increased by 10% and Shield Charge damage increased by 100%.\n(4) Set Arms: Damaging a target affected by Colossus Smash with Mortal Strike or Cleave that hits 3 or more targets extends Colossus Smash's effect on them by 1.0 sec.\n(4) Set Fury: Rampage reduces the cooldown of Odyn's Fury by 2.5 sec and Odyn's Fury damage is increased by an additional 10%. (1s cooldown)\n(4) Set Protection: Thunder Clap and Revenge damage increased by 10% and Shield Charge grants Revenge!\nSell Price:" }
entries[249951] = { ["name"] = "Night Ender's Chausses", ["text"] = "Binds when picked up\nLegs Plate\n27 Armor\n+9 [Strength or Intellect]\n+14 Stamina\n+ 5 Critical Strike\n+ 13 Haste\nClasses: Warrior\nRage of the Night Ender (0/5)\nNight Ender's Breastplate\nNight Ender's Fists\nNight Ender's Tusks\nNight Ender's Chausses\nNight Ender's Pauldrons\n(2) Set Arms: Mortal Strike and Cleave damage increased by 5%. Colossus Smash increases damage taken by an additional 5%.\n(2) Set Fury: Rampage damage increased by 10% and Odyn's Fury damage increased by 10%.\n(2) Set Protection: Shield Slam damage increased by 10% and Shield Charge damage increased by 100%.\n(4) Set Arms: Damaging a target affected by Colossus Smash with Mortal Strike or Cleave that hits 3 or more targets extends Colossus Smash's effect on them by 1.0 sec.\n(4) Set Fury: Rampage reduces the cooldown of Odyn's Fury by 2.5 sec and Odyn's Fury damage is increased by an additional 10%. (1s cooldown)\n(4) Set Protection: Thunder Clap and Revenge damage increased by 10% and Shield Charge grants Revenge!\nSell Price:" }
