entries[250105] = { ["name"] = "Sharktested Crest-Horn", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The Crest-Horn will often be drawn to graze on the plants that grow in the sea. Some have braved the fiercest wildlife there, making them true Kalu'ak.\"\nTrading Post" }
entries[250106] = { ["name"] = "Floestrider Crest-Horn", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The seldom seen native of the Azure Span is considered blessed by the tuskaar of the region.\"\nTrading Post" }
