entries[250108] = { ["name"] = "Cragstepper Crest-Horn", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Tuskaar aren't often found on Highmountain, but the crest-horns often come down to the shores to seek rare delicacies in the coastal waters.\"\nTrading Post" }
