entries[250191] = { ["name"] = "Reins of the Bilebound Ur'zul", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Bilebound Ur'zul.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:" }
entries[250192] = { ["name"] = "Reins of the Ghastly Ur'zul", ["text"] = "Legion Remix\nBinds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Ghastly Ur'zul.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\nSell Price:\n\"A ravenous breed of demon, the ghastly ur'zul tears through withered flesh and bone the way one would graze a salad.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250214] = { ["name"] = "Lightspire Core", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\nEquip: You are embraced by the Light, increasing Mastery by 20 .\n\nYour damaging spells and abilities can call a beam of radiant light nearby. Standing in the light blesses you with 35 Mastery while you stand in it.\n\"Stand in the Light, and be made whole.\"\nSell Price:" }
entries[250215] = { ["name"] = "Freightrunner's Flask", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\nUse: Take a sip of the drink you swiped from the freight, increasing your Critical Strike by 52 for 15 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[250223] = { ["name"] = "Soulcatcher's Charm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your damaging spells have a chance to haunt the target, dealing ( 180 * 12) Shadow damage over 12 sec.\n\nIf the target dies while haunted, the effect transfers to a nearby enemy, inflicting 150% of the Shadow damage over the remaining duration.\n\"Vordaza's necromantic fetish is covered in inscrutable carvings and has a heavy, ominous aura.\"\nSell Price:" }
entries[250224] = { ["name"] = "Mindpiercer's Sigil", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Your damaging spells have a chance to stir the Void near your target, erupting for 2491 Shadow damage split among nearby enemies. You siphon energy from the Void, gaining 52 Intellect for 10 sec.\nSell Price:" }
entries[250225] = { ["name"] = "Void Execution Mandate", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Agility\nUse: Mark your target for execution, increasing your Haste by 59 for 20 sec. While the target is marked, each of your attacks against them grants an additional 4 Critical Strike, as the Void urges you to finish the kill, up to a maximum of ( 4 * 15) Critical Strike. (2 Min Cooldown)\nSell Price:" }
entries[250226] = { ["name"] = "Latch's Crooked Hook", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nUse: Hurl a massive hook toward your target, cleaving through enemies in its path and dealing ( 1 * 577 ) Physical damage to each. When the hook crashes into the target, it inflicts ( 1 * 385 ) Physical damage split among enemies within 7 yards. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[250227] = { ["name"] = "Kroluk's Warbanner", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Your melee attacks have a chance to summon an elite Axethrower who hurls an axe at your target, inflicting ( 1 * 3676 ) Physical damage.\nSell Price:" }
entries[250228] = { ["name"] = "Resonant Bellowstone", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Your damaging abilities have a chance to echo with Xathuux's furious roar, increasing Critical Strike by 33 for 30 sec.\n\nDuring this time, each of your attacks increases your Critical Strike by an additional 5 , stacking up to a maximum of 5 times. (30s cooldown)\nSell Price:" }
entries[250229] = { ["name"] = "Idol of the War Loa", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Critical Strike\nEquip: You have proven your worth to Nalorakk. Your abilities have a chance to echo with the war god's furious roar, granting you 49 Strength for 15 sec.\n\nNearby allies with Nalorakk's favor are rallied, gaining 25% movement speed for 10 sec.\nSell Price:" }
