entries[250238] = { ["name"] = "Seed of the Devouring Wild", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Strength\nUse: Awaken the Bloodthorn Roots, erupting around your target and inflicting ( 492 * 1 ) Nature damage split among nearby enemies. You absorb their essence, gaining 29 Mastery for 10 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
