entries[250240] = { ["name"] = "Phase-Lost Slateback", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This Slateback got lost wandering into various phases as it followed some ethereals around.\"\nAchievement:\nPhase-Lost-and-Found\nCategory:\nWar Within" }
entries[250241] = { ["name"] = "Mark of Light", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Strength\nEquip: Your attacks have a chance to unleash a Radiant Strike at your target, dealing ( 816 * 1 ) Holy damage split among nearby enemies.\nSell Price:" }
entries[250242] = { ["name"] = "Jelly Replicator", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Taking damage has a chance to form a jelly shield for 10 sec, absorbing 40% of incoming damage, up to 4952 .\n\nIf your health falls below 35%, the jelly instinctively thickens around you for 5 sec, absorbing up to 2147 damage. This effect can only activate once every 1 min.\nSell Price:" }
entries[250243] = { ["name"] = "Manaheart's Binding Flame", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nUse: Form a Fel Shield for 10 sec, absorbing 30% of incoming damage, up to 1907 . While the shield holds, a portion of the absorbed damage is stored as volatile Fel energy.\n\nWhen the shield expires or breaks, the energy erupts and inflicts Fire damage to split between nearby enemies. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[250244] = { ["name"] = "Permafrost Essence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: You gain Nalorakk's Favor of Enduring. Taking damage has a chance to grant a Mark of Frost, increasing your Critical Strike by 36 for 15 sec. Stacks up to 10 times.\n\nIf your health falls below 25%, the reservoir ruptures, consuming all marks to form a Frost Barrier that absorbs 4567 damage per mark for 10 sec.\nSell Price:" }
entries[250245] = { ["name"] = "Tumor of the Swarm", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength]\nEquip: Your attacks have a chance to release toxic parasites that burst around you, dealing 964 Nature damage split among nearby enemies and healing you for 607 .\nSell Price:" }
entries[250246] = { ["name"] = "Refueling Orb", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your spells and abilities have a chance to release an energy orb that bounces between up to 5 nearby allies, increasing their Versatility by 13 for 12 sec. If an ally is below 50% health, the orb heals them for 514 instead.\nSell Price:" }
entries[250247] = { ["name"] = "Amulet of the Abyssal Hymn", ["text"] = "Binds when picked up\nNeck\n+8 Stamina\n+ 4 Haste\n+ 22 Mastery\n\nPrismatic Socket\nSell Price:" }
entries[250248] = { ["name"] = "Mycolic Medicine", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: You gain Nalorakk's Favor of Growth. Your healing spells and abilities have a chance to instantly heal your target for 1821 and spawn a glowing mushroom near them that lasts for 10 sec.\n\nIf an ally steps on and consumes the mushroom, they are healed for an additional 1041 .\n\"A draught from a species long lost everywhere but in dreams.\"\nSell Price:" }
entries[250249] = { ["name"] = "Founder's Point Gravestone", ["text"] = "3\nHousing Decor\nBinds to Warband\nUse: This Decor will be added immediately on purchase to your House Chest.\nSell Price:" }
