entries[250253] = { ["name"] = "Whisper of the Duskwraith", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nEquip: Your healing spells and abilities have a chance to release a spirit of the Duskwraith, leaping to your target and healing them for 1795 .\n\nIf the target's health is below 40%, the spirit empowers them further, granting 18 Versatility for 10 sec.\nSell Price:" }
entries[250254] = { ["name"] = "Seed of Radiant Hope", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nUse: Surround your target ally with Lightblossoms, healing them for [source value] over 12 sec.\n\nIf their health falls below 50%, the Lightblossoms fully bloom in radiant light, instantly healing them for 1225 . (1 Min, 30 Sec Cooldown)\nSell Price:", ["unresolvedValues"] = true }
entries[250255] = { ["name"] = "Unstable Felheart Crystal", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 Intellect\nUse: Unleash the fel energy stored within the crystal, sacrificing 824 of your health to infuse a target ally for 10 sec, absorbing 2178 damage. (2 Min Cooldown)\nSell Price:" }
entries[250256] = { ["name"] = "Heart of Wind", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to awaken the Heart of Wind, surrounding you with strong gales that increase your Haste by 56 for 10 sec.\nSell Price:" }
entries[250257] = { ["name"] = "Eye of the Drowning Void", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Intellect]\nEquip: Your damaging spells and abilities have a chance to tear open a rift of the Void within your target, erupting for ( 1 * 1242 ) Shadow damage split among nearby enemies.\nSell Price:" }
entries[250258] = { ["name"] = "Vessel of Tortured Souls", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 10 Mastery\nEquip: Your spells and abilities have a chance to awaken a soul within the vessel. Each soul you collect increases your Primary Stat by 9 for 1 min.\n\"Don't tap the glass. They don't like that.\"\nSell Price:" }
entries[250259] = { ["name"] = "Sapling of the Dawnroot", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+7 [Agility or Strength or Intellect]\nEquip: Your spells and abilities have a chance to uproot a Lightspawn Lasher to aid you in combat for 15 sec, dealing up to [source value] Physical damage.\n\nThe Lightspawn Lasher then withers, bursting into light-infused sap and inflicting ( 1 * 542 ) Holy damage split among nearby enemies.\nSell Price:", ["unresolvedValues"] = true }
