entries[250423] = { ["name"] = "Reins of the Slag Basilisk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Originally dwelling deep underground where their diet consisted of obsidian and basalt, the slag basilisks surfaced when their homes were disturbed by the Legion.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250424] = { ["name"] = "Reins of the Leystone Basilisk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This beautiful basilisk is often hunted for the magical properties of its organs. Fortunately for the basilisk, its connection to ley lines gives it a prescient sense of approaching predators.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250425] = { ["name"] = "Reins of the Felslate Basilisk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Once common on the Broken Isles, felslate basilisks have been hunted heavily by miners seeking their precious skins.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250426] = { ["name"] = "Reins of the Aquamarine Basilisk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Despite their name, aquamarine basilisks feast on a variety of coastal crystals and oceanic rocks.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250427] = { ["name"] = "Reins of the Illidari Blightstalker", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"These demons devour plague and relish in decay. Who thought it would be a good idea to ride them?\"\nWorld Event:\nWoW Remix: Legion" }
entries[250428] = { ["name"] = "Reins of the Illidari Dreadstalker", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Despite their taste for flesh and unnatural ability to smell fear, these lesser demons have been dominated by the Illidari as one would tame a hunting companion.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250429] = { ["name"] = "Reins of the Highland Elderhorn", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The hide of a highland elderhorn is incredibly thick. Never in recorded history has a highland elderhorn even blinked in response to insults thrown at them.\"\nWorld Event:\nWoW Remix: Legion" }
