entries[250627] = { ["name"] = "Forbidden Fork", ["text"] = "1\nForbidden Fork\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\n\"A fork from the Forbidden Reach. It's not that the fork itself is forbidden. That would be silly.\"" }
