entries[250693] = { ["name"] = "Altar of the Corrupted Flames", ["text"] = "3\nAltar of the Corrupted Flames\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nComplete the achievement \"Broken Isles World Quest V\"" }
entries[250694] = { ["name"] = "Draconic Metalshaper's Anvil", ["text"] = "5\nDraconic Metalshaper's Anvil\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the fourth milestone of the endeavor.\n\"Once used to shape metal purely for war, these anvils are now used by dracthyr artisans to make whatever they want.\"" }
entries[250695] = { ["name"] = "Replica Grathardormu's Hammer", ["text"] = "1\nReplica Grathardormu's Hammer\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the third milestone of the endeavor.\n\"A replica of a legendary hammer once used to swear an oath of vengeance. These replicas are often used by blacksmiths to infuse their craft with a bit of mystique.\"" }
entries[250696] = { ["name"] = "Green Thumb's Watering Can", ["text"] = "1\nGreen Thumb's Watering Can\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the first milestone of the endeavor.\n\"It's a watering can. Everyone needs a watering can. Even dracthyr.\"" }
entries[250697] = { ["name"] = "Draconic Auctioneer's Lectern", ["text"] = "3\nDraconic Auctioneer's Lectern\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the third milestone of the endeavor.\n\"A stylish lectern. Tavern tales tell that standing at once of these makes your speech increase in speed threefold.\"" }
entries[250698] = { ["name"] = "Obsidian Warder Pennant", ["text"] = "5\nObsidian Warder Pennant\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\n\"A banner proudly displaying the symbol of the Obsidian Warder weyrn.\"" }
entries[250699] = { ["name"] = "Dark Talon Pennant", ["text"] = "5\nDark Talon Pennant\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\n\"A banner proudly displaying the symbol of the Dark Talon weyrn.\"\nSell Price:" }
entries[250700] = { ["name"] = "Roasted Ram Leg", ["text"] = "1\nRoasted Ram Leg\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\n\"It's a succulent roasted leg of ram. Despite this, it is named after the inn of Valdrakken, and not just because it's a roasted leg of ram.\"" }
entries[250701] = { ["name"] = "Draconic Trader's Cart", ["text"] = "5\nDraconic Trader's Cart\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the first milestone of the endeavor.\n\"A status symbol for some, this stylish cart will let you transport anything smaller than it to wherever you need it to be.\"" }
entries[250702] = { ["name"] = "Artisan's Measuring Scales", ["text"] = "1\nArtisan's Measuring Scales\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the second milestone of the endeavor.\n\"Useful for measuring out ingredients or anything else that need weighing. Not recommended for weighing anything larger than a small dog. Or a very large rat.\"" }
entries[250703] = { ["name"] = "War Creche Teaching Crystal", ["text"] = "3\nWar Creche Teaching Crystal\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the second milestone of the endeavor.\n\"Crystals like these were once used to store Neltharion's teachings for the dracthyr. Not this one, though.\"" }
entries[250704] = { ["name"] = "Ancient Weyrn Device", ["text"] = "5\nAncient Weyrn Device\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nReach the fourth milestone of the endeavor.\n\"An ancient device from one of the dracthyr weyrns. It doesn't work anymore other than making a colorful glow.\"" }
