entries[250721] = { ["name"] = "Reins of the Snowy Highmountain Eagle", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"To find the feather of a snowy eagle in Highmountain is an omen of shifting winds and temperature drops.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250722] = { ["name"] = "Ethereal Stall", ["text"] = "Binds when picked up\nToy\nUse: Drop down an ethereal stall that lasts for 15 min. Can only be used outdoors. (15 Min Cooldown)" }
entries[250723] = { ["name"] = "Reins of the Treetop Highmountain Eagle", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The majestic eagle is a symbol of pride for the Highmountain tribes. This great beast's ability to carry tauren on their backs speaks to the sheer strength and size of the creatures of Highmountain.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250724] = { ["name"] = "Add Keystone Affix: Tyrannically Fortified", ["text"] = "Duration: 12 hrs (real time)\nUse: Add the Tyrannically Fortified affix to a Mythic Keystone.\nSell Price:" }
entries[250726] = { ["name"] = "Reins of the Leyfrost Manasaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding" }
entries[250727] = { ["name"] = "Reins of the Nightwell Manasaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding" }
entries[250728] = { ["name"] = "Reins of the Arcberry Manasaber", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Named for their resemblance to the bright berries made into arcwine, these proud cats have a keen awareness of the ley lines that travel beneath them.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250741] = { ["name"] = "Puzzling Cartel Chip", ["text"] = "The War Within Season 3\nBinds when picked up\nUnique (200)\n\"Only nine per customer. Spend it wisely!\"" }
entries[250745] = { ["name"] = "Reins of the Fel-Scarred Mana Ray", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Fel-Scarred Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\"Surviving on Argus is not an easy task. Its leathery hide scarred by fel corruption, this mana ray is prone to fits of aggression, moreso than usual.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250746] = { ["name"] = "Reins of the Bloodtooth Mana Ray", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Bloodtooth Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\"The shattering of Argus drove this breed of mana ray to bloodthirst. It now subsists on the corrupted blood of any creatures it can sink its many teeth into.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250747] = { ["name"] = "Reins of the Albino Mana Ray", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Albino Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\n\n\"The shattering of Argus caused the mana rays to mutate and adapt to their surroundings. Some of them abandoned their pigments in favor of strengthening their senses.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250748] = { ["name"] = "Reins of the Luminous Mana Ray", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a Luminous Mana Ray. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Mana rays can emit a bright glow to lure in prey.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250750] = { ["name"] = "Pouch of Sprouted Clippings", ["text"] = "Binds when picked up\nRequires Midnight Herbalism (25)\n\"Filled with herbs gathered during Abundance events.\"\n<Right Click to Open>" }
entries[250751] = { ["name"] = "Reins of the Twilight Courser", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"To evade predators, this courser dims its horn while hiding and flashes with dazzling radiance when provoked.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250752] = { ["name"] = "Reins of the Golden Sunrunner", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This free spirit enjoys long trots on the beach and frolicking through varicolored floral fields.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250753] = { ["name"] = "Bag of Cracked Orebits", ["text"] = "Binds when picked up\nRequires Midnight Mining (25)\n\"Filled with ore gathered during Abundance events.\"\n<Right Click to Open>" }
entries[250754] = { ["name"] = "Bag of Wild Skinnings", ["text"] = "Binds when picked up\nRequires Midnight Skinning (25)\n\"Filled with leather and scales gathered during Abundance events.\"\n<Right Click to Open>" }
entries[250755] = { ["name"] = "Pouch of Mystic Grindings", ["text"] = "Binds when picked up\nRequires Midnight Enchanting (25)\n\"Filled with enchanting materials gathered during Abundance events.\"\n<Right Click to Open>" }
entries[250756] = { ["name"] = "Reins of the Turquoise Courser", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Named for its uniquely colored eyes that seem to pierce your soul, the turquoise courser shows more intelligence than her dreamrunner cousins and is known to be an excellent judge of character.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250757] = { ["name"] = "Reins of the Gloomdark Nightmare", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Touched by the Emerald Nightmare, this creature's presence in one's dreams is an omen of misfortune. To see one while awake portends absolute catastrophe.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250758] = { ["name"] = "Reins of the Bonesteed of Oblivion", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of scarcity and death.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250759] = { ["name"] = "Reins of the Bonesteed of Plague", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of sickness and suffering.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250760] = { ["name"] = "Reins of the Bonesteed of Bloodshed", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of eternal strife.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250761] = { ["name"] = "Reins of the Bonesteed of Triumph", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"A good warhorse is loyal to its bones. Having shed its mortal coil, this steed is an omen of bold conquest.\"\nWorld Event:\nWoW Remix: Legion" }
