entries[250802] = { ["name"] = "Reins of the Longhorned Sable Talbuk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"The talbuks of Argus have grown long, coarse fur of brilliant colors that reflects the hues of their broken planet.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250803] = { ["name"] = "Garnet Ruinstrider", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Outfitted with sturdy barding, Argussian ruinstriders fearlessly carry their riders across the broken wastes of Argus and beyond.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250804] = { ["name"] = "Longhorned Bleakhoof Talbuk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Scarred by the chaos wrought by decades of conflict, this fel-infused steed is a perfect match for an intrepid adventurer.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250805] = { ["name"] = "Reins of the Longhorned Argussian Talbuk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"Few talbuks managed to remain unscathed despite the Legion's exploitation of their homeworld. Their tenacity is befitting of a noble steed.\"\nWorld Event:\nWoW Remix: Legion" }
entries[250806] = { ["name"] = "Reins of the Longhorned Beryl Talbuk", ["text"] = "Legion Remix\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nAvailable with the release of Legion Remix: Argus Eternal.\nAvailable with the release of Legion Remix: Rise of the Nightfallen.\n\n\"This wild talbuk found among the ruins of Argus has survived and persevered through decades of strife.\"\nWorld Event:\nWoW Remix: Legion" }
