entries[250927] = { ["name"] = "Quirky Turkey", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This creature might not be majestic but it certainly will turn heads!\"\nTrading Post" }
