entries[250929] = { ["name"] = "Prized Turkey", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This extra-large turkey not only took first place due to its pristine feathers, but also for its larger-than-average size.\"\nTrading Post" }
entries[250930] = { ["name"] = "Frostfall Groveglider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"These high-flying denizens of Azeroth's tallest trees have developed a thick, silky coat to adapt to even the coldest climates.\"\nIn-Game Shop" }
entries[250971] = { ["name"] = "Cindertuft Groveglider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Native to Hyjal, these mischievous tree-dwellers underwent a startling transformation when the Firelands made its appearance in the region.\"\nIn-Game Shop" }
entries[250972] = { ["name"] = "Gloombough Groveglider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Gloombough not only have uniquely dark coloring, but are entirely nocturnal, making them one of the rarest tree-dwellers to spot in person.\"\nIn-Game Shop" }
entries[250973] = { ["name"] = "Blossombranch Groveglider", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"These enchanting grovegliders are known for their coloring, reminiscent of some of Pandaria's treasured blossoming trees.\"\nIn-Game Shop" }
entries[250974] = { ["name"] = "Akil'zon's Updraft", ["text"] = "Binds when picked up\nToy\nUse: Call upon the favor of Akil'zon to ride the currents of the sky, levitating on a swirling gust of wind. (10 Min Cooldown)\nRequires Renown Rank 13 with the Amani Tribe." }
entries[250975] = { ["name"] = "Hellcaller Chest", ["text"] = "Binds when picked up\n\"Your first ten Hellcaller chests contain guaranteed Hellstone Shards. Additional chests have a low chance for additional Hellstone Shards. Also contains valorstones and otherworldly items.\"\n<Right Click to Open>" }
