entries[251487] = { ["name"] = "Prismatic Focusing Iris", ["text"] = "Optional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Your spells and abilities have a chance to activate the Iris, firing a focused beam of light at your target and dealing ( 1 * 1976 ) Arcane damage every second for 4 sec.\n\nEach unique gem color you have socketed empowers the Iris, causing it to deal 1% additional damage per.\nUsable with: Midnight recipes for most unembellished equipment.\n\"Can be bought and sold on the Auction House.\"\nSell Price:" }
